# solution.py
def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    def f(x):
        while x % k == 0:
            x //= k
        return x

    memo = {}

    def dfs(nums, path):
        state = tuple(sorted(nums))

        if state in memo:
            return memo[state]

        if len(nums) == 1:
            if f(nums[0]) == 1:
                memo[state] = path
                return path
            memo[state] = None
            return None

        best = None
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                x = nums[i]
                y = nums[j]
                new_val = f(x + y)
                new_nums = nums[:i] + nums[i+1:j+1] + [new_val]
                new_path = path + [(x, y)]

                result = dfs(new_nums, new_path)
                if result is not None:
                    best = result
                    break
            if best is not None:
                break

        memo[state] = best
        return best

    ops = dfs(a, [])

    if ops is None:
        return "NO"

    result = ["YES"]
    for x, y in ops:
        result.append(f"{x} {y}")
    return '\n'.join(result)
