```python
# conftest.py
def parse_input(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    # Build cost matrix where cost[i][j] is cost for city i to build rail to city j
    cost = [[0] * n for _ in range(n)]
    for i in range(n):
        parts = list(map(int, lines[i + 1].split()))
        # Line i contains N-1 elements: A_{i,1}, A_{i,2}, ..., A_{i,i-1}, A_{i,i+1}, ..., A_{i,N}
        # Position j in the line corresponds to city (j if j < i else j+1)
        for j_idx, c in enumerate(parts):
            j = j_idx if j_idx < i else j_idx + 1
            cost[i][j] = c

    return n, cost


def is_stable(assignment, n, cost):
    """Check if pairing is stable. Returns True if no blocking pair exists."""
    # assignment[i] is the partner of city i, or -1 if unmatched
    for u in range(n):
        if assignment[u] == -1:
            continue
        v = assignment[u]
        current_cost = cost[u][v]

        for w in range(n):
            if w == u:
                continue
            if assignment[w] != u:  # w is not paired with u
                other_partner = assignment[w] if assignment[w] != -1 else -1
                other_cost = cost[w][u] - cost[w][other_partner] if other_partner != -1 else 0 + cost[w][u]

                # Check if w prefers u over its current partner
                if other_partner != -1 and cost[w][u] < cost[w][other_partner]:
                    # Check if u also prefers w over current partner
                    if cost[u][w] < current_cost:
                        return False  # Found blocking pair

    return True


def solution(input_data):
    n, cost = parse_input(input_data)

    # Create a greedy initial matching and check for stability
    assignment = [-1] * n
    paired = [False] * n

    # Greedy pairing: each city picks best available partner
    for _ in range(n // 2):
        matched = False
        for u in range(n):
            if paired[u]:
                continue
            best_v = -1
            best_cost = float('inf')
            for v in range(n):
                if v != u and not paired[v]:
                    if cost[u][v] < best_cost:
                        best_cost = cost[u][v]
                        best_v = v
            if best_v != -1:
                assignment[u] = best_v
                assignment[best_v] = u
                paired[u] = paired[best_v] = True
                matched = True

        if not matched:
            break

    # Iteratively fix blocking pairs
    for _ in range(10 * n):
        if is_stable(assignment, n, cost):
            break

        # Find and fix blocking pair
        changed = False
        for u in range(n):
            if assignment[u] == -1:
                continue
            current_partner = assignment[u]
            current_cost = cost[u][current_partner]

            for v in range(n):
                if v == u or assignment[v] == -1 or assignment[v] != u:
                    continue

                other_partner = assignment[v]
                other_cost = cost[v][other_partner]

                # Check blocking pair condition
                if cost[u][v] < current_cost and cost[v][u] < other_cost:
                    assignment[u] = v
                    assignment[v] = u
                    changed = True
                    break

            if changed:
                break

    # Verify final stability
    if not is_stable(assignment, n, cost):
        return "-1\n"

    # Convert to output format (1-indexed)
    result = [str(assignment[i] + 1) if assignment[i] >= 0 else "-1" for i in range(n)]
    return "\n".join(result) + "\n"
