        a, b = b, a % b
    return a

def solve(x, y):
    if y == 0:
        return 0

    count = 0
    current_a = x
    current_y = y

    while current_y > 0:
        g = gcd(current_a, current_y)

        if g == 1:
            count += current_y
            break

        step = current_y // g
        max_step = current_y - (current_a % g)

        if current_y >= max_step:
            count += (max_step // g)
            current_y %= g
            if current_y < g:
                current_y += g
            if current_y > 0:
                continue

        ans = current_y // g
        if g == current_a // gcd(current_a, current_a // g):
            ans += 1

        count += ans
        current_y -= ans * g
        gcd_changed = False

    return count

def compute_f(x, y):
    if y == 0:
        return 0

    result = 0
    a = x
    b = y

    while b > 0:
        g = gcd(a, b)

        if g == 1:
            result += b
            return result

        q, r = divmod(b, g)

        while r == 0 or r >= g:
            if gcd(a, r) == g:
                steps = (r + g - 1) // g
                result += steps
                r -= steps * g
                if r == 0:
                    return result
                b = r
            else:
                break

        if b != 0:
            result += 1
            b -= b // g * g

    return result

def solution(input_str):
    lines = input_str.strip().split('\n')
    x, y = map(int, lines[0].split())
    return str(compute_f(x, y)) + '\n'
