import math

def get_coords(n, side, pos):
    """
    Get 2D coordinates for position pos along side of regular triangle.
    Triangle has vertices: (0,0), (n,0), (n/2, n*sqrt(3)/2)
    """
    sqrt3 = math.sqrt(3)

    if side == 0:  # Bottom: (0,0) to (n,0)
        return (pos, 0.0)
    elif side == 1:  # Right: (n,0) to (n/2, n*sqrt(3)/2)
        t = pos / n
        return (n * (1 - t) + n * 0, n * 0 + n * sqrt3 * t * 0.5)
    elif side == 2:  # Left: (n/2, n*sqrt(3)/2) to (0,0)
        t = pos / n
        return (n/2 * (1-t) + 0 * t, n*sqrt3/2 * (1-t) + 0 * t)

def dist_sq(p1, p2):
    return (p1[0] - p2[0])**2 + (p1[1] - p2[1])**2

def is_obtuse(p1, p2, p3):
    """Check if triangle with vertices p1, p2, p3 is obtuse"""
    a2 = dist_sq(p2, p3)
    b2 = dist_sq(p1, p3)
    c2 = dist_sq(p1, p2)

    # Degenerate triangle check
    if a2 + b2 + c2 < 1e-10:
        return False

    # Obtuse if one angle > 90 degrees
    return a2 > b2 + c2 + 1e-10 or b2 > a2 + c2 + 1e-10 or c2 > a2 + b2 + 1e-10

def solution(input_string):
    n, m = map(int, input_string.strip().split())

    # Available positions on each side: from m to n-m (inclusive)
    # These are positions where we can place vertices for triangles
    if n <= 2 * m:
        return "0\n"

    available = n - 2 * m
    count = 0

    for i in range(available):
        for j in range(available):
            for k in range(available):
                p0 = get_coords(n, 0, i)
                p1 = get_coords(n, 1, j)
                p2 = get_coords(n, 2, k)

                if is_obtuse(p0, p1, p2):
                    count += 1

    return f"{count}\n"

