import sys
sys.setrecursionlimit(200000)

MOD = 10**9 + 7

def solution(input_str):
    input_str = input_str.strip()

    class Parser:
        def __init__(self, s):
            self.s = s
            self.pos = 0
            self.n = len(s)

        def parse(self):
            return self._parse_expression()

        def _parse_expression(self):
            # expression ::= term | expression '+' term
            result = self._parse_term()
            while self.pos < self.n and self.s[self.pos] == '+':
                self.pos += 1
                result = self._concat(result, self._parse_term())
            return result

        def _parse_term(self):
            # term ::= number | number '-' number | number '(' expression ')'
            l_num, self.pos = self._parse_number(), self.pos

            if self.pos < self.n and self.s[self.pos] == '-':
                self.pos += 1
                r_num = self._parse_number()
                return self._concat_range(l_num, r_num)

            if self.pos < self.n and self.s[self.pos] == '(':
                self.pos += 1  # consume '('
                expr = self._parse_expression()
                if self.pos < self.n and self.s[self.pos] == ')':
                    self.pos += 1  # consume ')'
                return self._rep(l_num, expr)

            return result

        def _parse_number(self):
            n = 0
            while self.pos < self.n and '0' <= self.s[self.pos] <= '9':
                n = (n * 10 + int(self.s[self.pos])) % MOD
                self.pos += 1
            return n

        def _concat(self, a, b):
            # Concatenate a and b: result = a * 10^len(b) + b
            len_b = self.get_len(b)
            return (a * pow(10, len_b, MOD) + b) % MOD

        def get_len(self, value):
            # For actual numbers, compute length
            if value == 0:
                return 1
            length = 0
            temp = value
            while temp > 1:
                temp //= 10
                length += 1
            if temp == 0:
                length += 1
            return length

        def _get_len_range(self, l, r):
            # Calculate the total number of digits in concatenation of l to r
            if l == r:
                return len(str(l))
            i, length = l, 0
            while i <= r:
                length += len(str(i))
                i += 1
            return length

        def _concat_range(self, l, r):
            # Concatenate all numbers from l to r
            if l == r:
                return l

            # We'll compute this using digit contribution
            count = 1  # count of digits from 1 to l-1
            total_len = 0  # total length of concatenation from l to r

            # Count digits in range l to r
            count += (r - l + 1)
            total_len = (total_len + count) % MOD

            # Compute the actual concatenation
            result = self._build_range(l, r)
            return result

        def _build_range(self, l, r):
            # Build concatenation from l to r
            if l == r:
                return l

            # Use mathematical approach to compute digits contribution
            result = 0
            for i in range(l, r + 1):
                result = (result * pow(10, len(str(i)), MOD) + i) % MOD
            return result

        def _rep(self, n, expr):
            # Repeat expr n times
            # First get length of expr
            len_expr = self.get_len(expr)
            result = expr

            for _ in range(n - 1):
                result = self._concat(result, expr)
            return result

    parser = Parser(input_str)
    result = parser.parse()
    return str(result)
