import sys
from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in lines[1:]:
        if i:
            u, v = map(int, i.split())
            adj[u].append(v)

    # BFS from each node to compute shortest distances
    dist = [[float('inf')] * (n + 1) for _ in range(n + 1)]

    for start in range(1, n + 1):
        dist[start][start] = 0
        q = deque([start])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[start][v] > dist[start][u] + 1:
                    dist[start][v] = dist[start][u] + 1
                    q.append(v)

    # Find the best quadruple (a, b, c, d) maximizing:
    # dist[a][b] + dist[b][c] + dist[c][d]
    max_total = -1
    best_quadruple = None

    # We need to efficiently search for the optimal path
    # Try all ordered quadruples - O(n^4) is too slow for n=3000
    # But we can optimize by limiting search space

    # Strategy: For each starting node a, for each second node b (reachable from a),
    # for each third node c (reachable from b), try all reachable d from c

    # Actually, to keep it better than O(n^4), we can be selective
    # Find nodes with valid paths (dist != inf)

    for a in range(1, n + 1):
        for b in range(1, n + 1):
            if a == b or dist[a][b] == float('inf'):
                continue
            for c in range(1, n + 1):
                if b == c or c == a or dist[b][c] == float('inf'):
                    continue
                for d in range(1, n + 1):
                    if d == a or d == b or d == c or dist[c][d] == float('inf'):
                        continue
                    total = dist[a][b] + dist[b][c] + dist[c][d]
                    if total > max_total:
                        max_total = total
                        best_quadruple = (a, b, c, d)

    if best_quadruple:
        return f"{best_quadruple[0]} {best_quadruple[1]} {best_quadruple[2]} {best_quadruple[3]}"
    else:
        # Should not happen based on problem guarantee
        return "1 2 3 4"
