        parts = lines[i + 1].split()
        if len(parts) >= 2:
            u, v = int(parts[0]), int(parts[1])
            adj[u].append((v, i + 1))
            adj[v].append((u, i + 1))

    # BFS to count component size from a starting node, avoiding a specific edge
    def bfs_component_size(start, edge_to_avoid):
        visited = [False] * (n + 1)
        queue = deque([start])
        visited[start] = True
        size = 0

        while queue:
            node = queue.popleft()
            size += 1
            for neighbor, idx in adj[node]:
                if not visited[neighbor] and idx != edge_to_avoid:
                    visited[neighbor] = True
                    queue.append(neighbor)
        return size

    # Strategy 1: Try removing a single edge that creates a component of size k
    best_count = 2
    best_edges = []

    for i in range(len(lines) - 1):
        parts = lines[i + 1].split()
        if len(parts) >= 2:
            u, v = int(parts[0]), int(parts[1])

            size_u = bfs_component_size(u, i + 1)
            size_v = bfs_component_size(v, i + 1)

            # Check if either resulting component has exactly k cities
            if size_u == k or size_v == k:
                best_count = 1
                best_edges = [i + 1]
                return str(best_count) + "\n" + " ".join(map(str, best_edges))

    # Strategy 2: Find connected subgraphs (subtrees) of size k with minimum boundary
    min_boundary = n
    result_edges = []
    found = False

    def get_boundary(subset):
        """Count edges connecting vertices in subset to vertices outside"""
        boundary = 0
        for node in subset:
            for neighbor, idx in adj[node]:
                if neighbor not in subset:
                    boundary += 1
        return boundary

    # DFS to enumerate all connected subgraphs of size k
    def dfs(u, parent, current_set, visited_nodes):
        nonlocal min_boundary, result_edges, found

        if len(current_set) == k:
            boundary = get_boundary(current_set)
            if boundary < min_boundary or (boundary == min_boundary and not found):
                min_boundary = boundary
                result_edges = list(current_set)  # Store edge indices
                found = True
            return

        for neighbor, idx in adj[u]:
            if neighbor != parent and neighbor not in current_set:
                current_set.add(neighbor)
                dfs(neighbor, u, current_set, visited_nodes)
                current_set.remove(neighbor)

    # Try starting from each node
