def solution(data):
    lines = data.strip().split('\n')
    if not lines:
        return "0"

    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    pairs = []
    for i in range(2, 2 + m):
        if i < len(lines):
            u, v = map(int, lines[i].split())
            pairs.append((u - 1, v - 1))

    def factorize(x):
        factors = {}
        d = 2
        temp = x
        while d * d <= temp:
            while temp % d == 0:
                factors[d] = factors.get(d, 0) + 1
                temp //= d
            d += 1
        if temp > 1:
            factors[temp] = factors.get(temp, 0) + 1
        return factors

    num_factors = [factorize(a[i]) for i in range(n)]

    all_primes = set()
    for factors in num_factors:
        all_primes.update(factors.keys())

    from collections import deque

    total_ops = 0

    source = 2 * n + 1
    sink = 2 * n + 2
    num_nodes = 2 * n + 3

    for prime in all_primes:
        capacity = {}
        for i in range(num_nodes):
            for j in range(num_nodes):
                capacity[(i, j)] = 0

        graph = [[] for _ in range(num_nodes)]

        for i in range(n):
            if num_factors[i].get(prime, 0) > 0:
                if (i + 1) % 2 != 0:
                    cap = num_factors[i].get(prime, 0)
                    capacity[(source, i)] = cap
                    capacity[(i, source)] = 0
                    if i not in graph[source]:
                        graph[source].append(i)
                    if source not in graph[i]:
                        graph[i].append(source)

        for i in range(n):
            if num_factors[i].get(prime, 0) > 0:
                if (i + 1) % 2 == 0:
                    cap = num_factors[i].get(prime, 0)
                    capacity[(i + n, sink)] = cap
                    capacity[(sink, i + n)] = 0
                    if i + n not in graph[sink]:
                        graph[sink].append(i + n)
                    if sink not in graph[i + n]:
                        graph[i + n].append(sink)

        for u, v in pairs:
            cap = min(num_factors[u].get(prime, 0), num_factors[v].get(prime, 0))
            if cap > 0:
                qux = u if (u + 1) % 2 != 0 else v
                qux2 = v if (u + 1) % 2 != 0 else u
                capacity[(qux, qux2 + n)] = cap
                capacity[(qux2 + n, qux)] = 0
                if qux not in graph[qux2 + n]:
                    graph[qux2 + n].append(qux)
                if qux2 + n not in graph[qux]:
                    graph[qux].append(qux2 + n)

        flow = 0
        while True:
            parent = [-1] * num_nodes
            queue = deque([source])
            parent[source] = source
            found_path = False

            while queue:
                curr = queue.popleft()
                if curr == sink:
                    found_path = True
                    break

                for nxt in graph[curr]:
                    if parent[nxt] == -1 and capacity.get((curr, nxt), 0) > 0:
                        parent[nxt] = curr
                        queue.append(nxt)

            if not found_path:
                break

            if parent[sink] == -1:
                break

            bottleneck = float('inf')
            curr = sink
            while curr != source:
                prev = parent[curr]
                bottleneck = min(bottleneck, capacity[(prev, curr)])
                curr = parent[curr]

            flow += bottleneck

            curr = sink
            while curr != source:
                prev = parent[curr]
                capacity[(prev, curr)] = capacity[(prev, curr)] - bottleneck
                capacity[(curr, prev)] = capacity[(curr, prev)] + bottleneck
                curr = parent[curr]

        total_ops += flow

    return str(total_ops)
