    class FenwickTree:
        def __init__(self, n):
            self.n = n
            self.tree = [0] * (n + 1)

        def update(self, i, delta):
            i += 1  # 1-indexed
            while i <= self.n:
                self.tree[i] += delta
                i += i & (-i)

