    def check(pressed):
        """Check if pressing these buttons wins (no counter has value == corresponding a[i])"""
        cnt_vals = defaultdict(int)

        # Calculate final values for each counter
        for i in pressed:
            cnt_vals[i-1] += 1
            for neighbor in adj[i-1]:
                cnt_vals[neighbor-1] += 1

        for i in range(n):
            if cnt_vals[i] == a[i]:
                return False
        return True

    def solve():
        # Try pressing each counter individually first
        for i in range(n):
            pressed = [i+1]
            if check(pressed):
                # Verify no counter reaches wrong value
                cnt_vals = defaultdict(int)
                for j in pressed:
                    cnt_vals[j-1] += 1
                    for neighbor in adj[j-1]:
                        cnt_vals[neighbor-1] += 1

                result = [i+1]
                for j in range(n):
                    if cnt_vals[j] != a[j]:
                        result.append(j+1)
                    else:
                        return str(-1)

                return str(len(result) - 1) + '\n' + ' '.join(map(str, sorted(result)))

        return None

    result = solve()
    if result:
        return result
    else:
        # More comprehensive solution needed
        result = None

        # Try empty set
        if check([]):
            return "0\n"

        # Try all single counter presses
        for press_list in [[i+1] for i in range(n)]:
            if check(press_list):
                # Build full solution
                pressed_set = set(press_list)
                in_result = [False] * n

                for i in range(n):
                    values = defaultdict(int)
                    if i in pressed_set:
                        values[i] += 1

                    for neighbor in adj[i]:
                        values[neighbor] += 1

                    if values[i] != a[i]:
                        in_result[i] = True

                if any(in_result):
                    result_indices = [i+1 for i in range(n) if in_result[i]]
                    return str(len(result_indices)) + '\n' + ' '.join(map(str, result_indices))

        # If we can't find any solution
        found = False
        for i in range(n):
