        si = parts[0]
        ics = parts[1:]
        vertex_types.append(ics)

    # Find the maximum number of ice cream types at any vertex
    # This gives us the chromatic number for the conflict graph
    c = max(len(ics) for ics in vertex_types)

    if m == 0:
        return f"{c}\n"

