    # We use a simpler approach: process vertices and add edges between all pairs
    type_adj = [[] for _ in range(m)]

    for v_idx, ics in enumerate(vertex_types):
        for i in range(len(ics)):
            for j in range(i + 1, len(ics)):
                t1, t2 = ics[i] - 1, ics[j] - 1
                if t2 not in type_adj[t1]:
                    type_adj[t1].append(t2)
                    type_adj[t2].append(t1)

    # Greedy coloring: assign smallest available color to each type
    colors = [0] * m

    # For consistency with the problem, sort processing by which types appear
    # Use a stable order based on type index
    def get_color(idx):
        used = [False] * (c + 2)
        for neighbor in type_adj[idx]:
